INSERT INTO `message` VALUES (1,'사장님, 안녕하세요. 제안서 하나 보냅니다 검토 부탁드립니다.','2025-09-15 14:30:00.000000',NULL,_binary '','TEXT',1,6,NULL),(2,'작가님, 안녕하세요. 제안서 잘 받았습니다. 긍정적으로 검토해보겠습니다.','2025-09-15 16:00:00.000000',NULL,_binary '','TEXT',1,11,NULL),(3,'작품 실물을 한번 보고 싶은데, 언제가 괜찮으신가요?','2025-09-16 10:00:00.000000',NULL,_binary '','TEXT',1,11,NULL),(4,'네, 좋습니다. 저는 내일 오후 3시 이후로는 다 괜찮습니다.','2025-09-16 10:05:00.000000',NULL,_binary '','TEXT',1,6,NULL),(5,'그럼 내일 3시에 작가님 작업실로 찾아뵙겠습니다.','2025-09-16 11:20:00.000000',NULL,_binary '','TEXT',1,11,NULL),(6,'사장님, 제 작품 \'산의 아침\'을 전시하고 싶어 제안 드립니다.','2025-09-18 08:45:00.000000',NULL,_binary '','TEXT',1,6,1),(7,NULL,'2025-09-18 09:00:00.000000',NULL,_binary '','PROPOSAL',1,6,21),(8,'작가님, 제안 감사합니다. 저희 카페와 잘 어울릴 것 같네요 :)','2025-09-18 11:30:00.000000',NULL,_binary '','TEXT',1,11,NULL),(9,NULL,'2025-09-22 10:00:00.000000',NULL,_binary '','AGREED',1,11,21),(10,'네 사장님, 그럼 잘 부탁드립니다.','2025-09-22 15:30:00.000000',NULL,_binary '','TEXT',1,6,NULL),(11,NULL,'2025-10-07 00:00:00.000000',NULL,_binary '','STARTED',1,NULL,21),(12,'작가님, 전시 시작 후에 손님들 반응이 정말 뜨겁습니다! 작품 덕분에 카페 분위기가 한층 더 좋아졌어요.','2025-10-10 14:00:00.000000',NULL,_binary '','TEXT',1,11,NULL),(13,'사장님, 좋은 말씀 감사합니다. 많은 분들이 제 작품을 좋아해주신다니 기쁘네요.','2025-10-11 10:30:00.000000',NULL,_binary '','TEXT',1,6,NULL),(14,'네, 덕분에 매출도 많이 늘었습니다! 정말 감사합니다.','2025-10-15 16:00:00.000000',NULL,_binary '','TEXT',1,11,NULL),(15,NULL,'2025-10-21 23:59:59.000000',NULL,_binary '','ENDED',1,NULL,21),(16,'사장님, 안녕하세요. 벨빌베이크하우스에 어울릴 만한 제 작품이 몇 점 있는데, 전시 의향이 있으신지 궁금합니다.','2025-10-10 11:00:00.000000',NULL,_binary '','TEXT',2,6,NULL),(17,'안녕하세요, 작가님. 저희 카페에 관심을 가져주셔서 감사합니다. 어떤 작품들인지 볼 수 있을까요?','2025-10-10 11:30:00.000000',NULL,_binary '','TEXT',2,12,NULL),(18,'네, 제 프로필에 있는 \'겨울 산\'과 \'여름 바다\'라는 작품입니다. 한번 보시고 의견 주세요.','2025-10-10 11:32:00.000000',NULL,_binary '','TEXT',2,6,NULL),(19,'사장님, 안녕하세요. 페트리코 카페의 메인 홀 벽에 제 작품 \'숲속 오솔길\'을 전시하고 싶어 제안 드립니다.','2025-10-11 10:00:00.000000',NULL,_binary '','TEXT',4,6,20),(20,NULL,'2025-10-11 10:00:00.000000',NULL,_binary '','PROPOSAL',4,6,20),(21,'작가님, 제안 감사합니다. 저희 카페와 잘 어울릴 것 같네요. 긍정적으로 검토 후 연락드리겠습니다.','2025-10-11 11:30:00.000000',NULL,_binary '','TEXT',4,13,NULL),(22,NULL,'2025-10-12 15:00:00.000000',NULL,_binary '','AGREED',4,13,20),(23,NULL,'2025-10-15 00:00:00.000000',NULL,_binary '','STARTED',4,NULL,20),(24,NULL,'2025-10-29 23:59:59.000000',NULL,_binary '','ENDED',4,NULL,20),(25,'작가님, 팬입니다! 이번에 전시하신 \'도시의 밤\' 작품 너무 멋져요! 혹시 구매할 수 있나요?','2025-10-20 18:00:00.000000',NULL,_binary '','TEXT',11,1,NULL),(26,'안녕하세요. 좋게 봐주셨다니 정말 기쁘네요. 감사합니다! 아쉽지만 그 작품은 현재 판매하지 않고 있습니다. ㅠ.ㅠ','2025-10-21 09:10:00.000000',NULL,_binary '','TEXT',11,6,NULL),(27,'아쉽네요. 알겠습니다. 다음 작품도 기대할게요!','2025-10-21 09:15:00.000000',NULL,_binary '','TEXT',11,1,NULL),(28,'사장님, 너와숲 카페에 지금 전시 중인 작품이 있나요?','2025-11-10 13:00:00.000000',NULL,_binary '','TEXT',14,1,NULL),(29,'네, 안녕하세요. 지금 ArtistUser1 작가님의 \'산의 아침\' 작품이 전시 중입니다. 이번달 말까지 전시 예정이에요.','2025-11-10 13:05:00.000000',NULL,_binary '','TEXT',14,11,1),(30,'정보 감사합니다! 보러 가야겠어요.','2025-11-10 13:07:00.000000',NULL,_binary '','TEXT',14,1,NULL),(31,'안녕하세요','2025-11-20 09:50:30.922188',NULL,_binary '','TEXT',21,6,NULL),(32,'카페가 너무 예뻐요','2025-11-20 09:50:34.129016',NULL,_binary '','TEXT',21,6,NULL),(33,'안녕하세요 좋게 봐주셔서  감사합니다!','2025-11-20 09:50:35.829296',NULL,_binary '','TEXT',21,14,NULL),(34,NULL,'2025-11-20 09:50:58.105284',NULL,_binary '','PROPOSAL',21,6,71),(35,'감사합니다ㅎㅎ','2025-11-20 09:51:00.804478',NULL,_binary '','TEXT',21,14,NULL),(36,NULL,'2025-11-20 09:51:04.090317',NULL,_binary '','AGREED',21,14,71);
