  CONSTRAINT `FK4d7357j3sd363vrda0yf49tmf` FOREIGN KEY (`exhibition_id`) REFERENCES `exhibition` (`id`),
  CONSTRAINT `FKenij2ljq81n3pod8043qcjncb` FOREIGN KEY (`reviewee_id`) REFERENCES `users` (`id`)
